import{_ as t,o as p,c as a,a5 as r}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"2025/06/13","description":"","frontmatter":{},"headers":[],"relativePath":"trip/journey/20250613.md","filePath":"trip/journey/20250613.md","lastUpdated":1752144819000}'),o={name:"trip/journey/20250613.md"};function _(n,e,s,i,d,c){return p(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2025-06-13" tabindex="-1">2025/06/13 <a class="header-anchor" href="#_2025-06-13" aria-label="Permalink to &quot;2025/06/13&quot;">​</a></h1><p>适逢机场大面积延误，19:25登机，18:51赶到贵宾厅已经很赶了，因为19点自助餐就结束了。接待前台人非常多，大多都是延误旅客，要么改签，要么升舱，要么抱怨。当然，还有我前面那位，墨迹，只是单纯的墨迹，一点不像个男的。</p><p>给完身份证后，就请求升舱，工作人员帮他打电话升舱，被告知不可升舱。这个小伙表示，“航旅纵横前面有座位的呀，怎么会不能升”。半天蹦出一个字，说话慢条斯理的。而后工作人员告知“航班延误到22点”，小伙“啊我航旅纵横没有说延误啊”，工作人员发问“那你改签还是怎样”……就这样沟通了许久。</p><p>到我时，已经19:00整。不出所料，到了餐厅，自助餐或被吃光，或被收走，只有一碗小面得以享用，凑合着吃吧。</p><p>来到贵宾厅，遇到“高素质”人才，翘着二郎腿，脚踩在茶几上，外放短视频，太尊贵了！唉，离他远点吧。坐下吃点零食，人才又开始打电话，声音非常大，免提外放打电话，时而粤语时而广普，哈哈。</p><p>因为大面积延误堆积的航班，突然全部放行，工作人员人手不够，登机都没人接待。等了一小会。</p><p>机长似乎是预判了其他晚点航司可能会插队，提前了10分钟登机。但还是被插队了，46分登机结束，直到8分才推出。</p><p>……</p><p>开始卖东西，没劲，看向窗外，好圆好亮的月亮。拍了几张照片，都有反光，机舱灯光太亮了。 21:45广播开始下降，而后，21:46 开始持续颠簸，似乎直接插入厚厚的云层，上下起伏，还好嚼着口香糖，不然该反胃了。月亮自然也消失在云里。52分，颠簸停止，月亮显现。每当月光隐匿，颠簸便会再次出现。</p><p>可惜，客舱灯光全部关掉的时候，月亮也不见了。</p><p>出口出来，去厕所，</p>',11)])])}const u=t(o,[["render",_]]);export{m as __pageData,u as default};
